function main() {
  const rootDir = process.cwd();
  const backupDir = path.join(rootDir, '.backup-before-tltv');

  console.log('====================================================================');
  console.log('🚀 BẮT ĐẦU CẬP NHẬT KHÓA HỌC, LỘ TRÌNH & ƯU ĐÃI HỌC BỔNG (BELIEF ENGLISH)');
  console.log('====================================================================');

  if (!fs.existsSync(backupDir)) {
    fs.mkdirSync(backupDir, { recursive: true });
  }

  let updatedCount = 0;

  for (const [relPath, newContent] of Object.entries(FILES_TO_UPDATE)) {
    const targetPath = path.join(rootDir, relPath);
    const targetDir = path.dirname(targetPath);

    if (!fs.existsSync(targetDir)) {
      fs.mkdirSync(targetDir, { recursive: true });
    }

    // Sao lưu file cũ nếu tồn tại
    if (fs.existsSync(targetPath)) {
      const backupPath = path.join(backupDir, relPath);
      fs.mkdirSync(path.dirname(backupPath), { recursive: true });
      fs.copyFileSync(targetPath, backupPath);
    }

    // Ghi nội dung mới chuẩn UTF-8
    fs.writeFileSync(targetPath, newContent, 'utf8');
    updatedCount++;
    console.log(`✅ Đã cập nhật an toàn: ${relPath}`);
  }

  // Bước tự động kiểm tra (Self-Verification)
  console.log('\n🔍 ĐANG TỰ ĐỘNG KIỂM TRA LẠI CÁC FILE SAU KHI CẬP NHẬT...');
  const siteJsonPath = path.join(rootDir, 'data/site-content.json');
  const parsedJson = JSON.parse(fs.readFileSync(siteJsonPath, 'utf8'));
  if (!Array.isArray(parsedJson.courses) || parsedJson.courses.length !== 7) {
    throw new Error('Lỗi kiểm tra: data/site-content.json không đủ 7 trình độ chuẩn!');
  }

  const coursesTs = fs.readFileSync(path.join(rootDir, 'src/data/coursesData.ts'), 'utf8');
  const requiredCodes = ['MOI', 'GT', '4KH', '6KH', 'CV2C', 'OLD', 'BOOK'];
  for (const code of requiredCodes) {
    if (!coursesTs.includes(`code: '${code}'`)) {
      throw new Error(`Lỗi kiểm tra: Thiếu mã ưu đãi ${code} trong src/data/coursesData.ts`);
    }
  }

  console.log(`✅ Kiểm tra JSON hợp lệ: ${parsedJson.courses.length} trình độ (STA, MOV, FLY, KET, PET, IEL, ADT)`);
  console.log(`✅ Kiểm tra 7 mã ưu đãi học bổng: ${requiredCodes.join(', ')}`);
  console.log(`✅ Đã sao lưu bản cũ tại: .backup-before-tltv/`);
  console.log(`🎉 HOÀN TẤT CẬP NHẬT ${updatedCount} FILE THÀNH CÔNG 100% KHÔNG LỖI!`);
}

main();
